def _capacity_counts(self, user=None):
    """非下线会话计数（排队项不计数）：返回 (总数, 该用户数)。"""
    total_count = 0
    user_count = 0
    for session in self._sessions.values():
        if session["state"] != _STATE_OFFLINE:
            total_count += 1
            if user is not None and session["user"] == user:
                user_count += 1
